@Composable fun TavernCreationScreen(vm:TavernCreationViewModel=hiltViewModel(),onCreated:()->Unit){val s by vm.ui.collectAsState();LaunchedEffect(s.created){if(s.created)onCreated()};Column(Modifier.fillMaxSize().padding(24.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){Text("Fundar sua taberna");TavernPreview(s.name,s.emblem);TavernNameField(s.name,vm::name);TavernEmblemSelector(s.emblem,vm::emblem);GoldButton("Fundar Taberna",vm::save,enabled=s.name.isNotBlank()&&!s.saving)}}
